<!doctype html>
<html lang="<?= \App\Core\Localization::current() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= \App\Core\t("Sign in") ?> — c0m.me</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><?php require __DIR__ . '/partials/language-switcher.php'; ?><main class="auth-wrap"><a class="brand" href="/">c0m.me</a><section class="auth-card"><span class="eyebrow">ACCOUNT CENTER</span><h1><?= \App\Core\t("Welcome back") ?></h1><p><?= \App\Core\t("<?= \App\Core\t("Sign in") ?> to continue to your c0m.me ecosystem.") ?></p><?php if (($_GET['password_changed'] ?? '') === '1'): ?><div class="alert" style="background:#eaf7ef;color:#23643c"><?= \App\Core\t("Your password was changed. Please sign in again.") ?></div><?php endif; ?><?php if (!empty($error)): ?><div class="alert"><?= htmlspecialchars(\App\Core\t($error), ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><form method="post" action="/login"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token(), ENT_QUOTES, 'UTF-8') ?>"><label><?= \App\Core\t("Email address") ?></label><input type="email" name="email" autocomplete="username" required><label><?= \App\Core\t("Password") ?></label><input type="password" name="password" autocomplete="current-password" required><small><a href="/forgot-password"><?= \App\Core\t("Forgot password?") ?></a></small><button class="button full" type="submit"><?= \App\Core\t("Sign in") ?></button></form><small>New here? <a href="/register"><?= \App\Core\t("Create an account") ?></a></small></section></main></body></html>
